import 'dart:typed_data';\n\n/// Procesador de audio para reconocimiento rápido tipo Shazam\n///\n/// Extrae características del audio para reconocimiento rápido\n/// y optimiza el tamaño de datos enviados a la API.\nclass AudioProcessor {\n  /// Extrae fingerprint de audio para reconocimiento rápido\n  /// Similar al algoritmo de Shazam: espectrograma → hashes\n  static List<int> extractAudioFingerprint(List<int> audioBytes) {\n    // Convertir a Float32 para procesamiento\n    final audioFloat = _bytesToFloat32(audioBytes);\n\n    // 1. Normalización de amplitud\n    final normalized = _normalizeAudio(audioFloat);\n\n    // 2. Extraer segmentos de 0.5 segundos (Shazam usa segmentos cortos)\n    const segmentDuration = 0.5; // segundos\n    const sampleRate = 44100; // Hz\n    const segmentSamples = (segmentDuration * sampleRate).toInt();\n    \n    if (normalized.length < segmentSamples) {\n      return audioBytes.sublist(0, min(audioBytes.length, 10000));\n    }\n\n    // 3. Tomar el primer segmento de 0.5 segundos (Shazam identifica con poco audio)\n    final startSegment = normalized.sublist(0, min(segmentSamples, normalized.length));\n    \n    // 4. Convertir segmento a bytes optimizados\n    return _float32ToBytes(startSegment);\n  }\n\n  /// Optimizar audio para envío a API\n  static List<int> optimizeForApi(List<int> audioBytes) {\n    // Reducir calidad para envío rápido\n    // Shazam solo necesita ~10KB para identificar\n    const targetSize = 10000; // 10KB máximo\n    \n    if (audioBytes.length <= targetSize) {\n      return audioBytes;\n    }\n\n    // Tomar el primer segundo de audio (Shazam funciona con poco)\n    // 1 segundo @ 44.1kHz mono = ~44K muestras\n    // 1 segundo @ 16 bits = ~88KB\n    // Reducimos a muestras cada 8\n    final optimized = <int>[];\n    for (int i = 0; i < min(audioBytes.length, 88000); i += 8) {\n      optimized.add(audioBytes[i]);\n    }\n\n    return optimized;\n  }\n\n  /// Verificar calidad de audio para reconocimiento\n  static bool isAudioQualityGood(List<int> audioBytes) {\n    if (audioBytes.isEmpty) return false;\n    \n    // Verificar amplitud (no silencio)\n    final floatAudio = _bytesToFloat32(audioBytes);\n    final avgAmplitude = _calculateAverageAmplitude(floatAudio);\n    \n    // Umbral mínimo de amplitud\n    return avgAmplitude > 0.05;\n  }\n\n  /// Calcular nivel de ruido vs señal\n  static double calculateSignalToNoise(List<int> audioBytes) {\n    final floatAudio = _bytesToFloat32(audioBytes);\n    if (floatAudio.isEmpty) return 0.0;\n    \n    // Calcular energía de la señal\n    double signalEnergy = 0.0;\n    for (final sample in floatAudio) {\n      signalEnergy += sample * sample;\n    }\n    signalEnergy /= floatAudio.length;\n    \n    // Estimación simple de SNR\n    return signalEnergy > 0.0001 ? 10.0 * log10(signalEnergy / 0.0001) : 0.0;\n  }\n\n  // ─── Helpers privados ───\n\n  static List<double> _bytesToFloat32(List<int> bytes) {\n    final floats = <double>[];\n    const bytesPerSample = 2; // WAV 16-bit\n    \n    for (int i = 0; i < bytes.length - bytesPerSample; i += bytesPerSample) {\n      // Convertir bytes 16-bit signed a float [-1.0, 1.0]\n      final sample = (bytes[i] | (bytes[i + 1] << 8)).toSigned(16);\n      floats.add(sample / 32768.0);\n    }\n    \n    return floats;\n  }\n\n  static List<int> _float32ToBytes(List<double> floats) {\n    final bytes = <int>[];\n    \n    for (final sample in floats) {\n      // Convertir float [-1.0, 1.0] a int16\n      final int16 = (sample * 32768.0).clamp(-32768, 32767).toInt();\n      bytes.add(int16 & 0xFF);\n      bytes.add((int16 >> 8) & 0xFF);\n    }\n    \n    return bytes;\n  }\n\n  static List<double> _normalizeAudio(List<double> audio) {\n    if (audio.isEmpty) return [];\n    \n    // Encontrar máximo absoluto\n    double maxAbs = 0.0;\n    for (final sample in audio) {\n      maxAbs = max(maxAbs, sample.abs());\n    }\n    \n    if (maxAbs == 0.0) return audio;\n    \n    // Normalizar a [-1.0, 1.0]\n    return audio.map((sample) => sample / maxAbs).toList();\n  }\n\n  static double _calculateAverageAmplitude(List<double> audio) {\n    if (audio.isEmpty) return 0.0;\n    \n    double sum = 0.0;\n    for (final sample in audio) {\n      sum += sample.abs();\n    }\n    \n    return sum / audio.length;\n  }\n\n  static T min<T extends Comparable>(T a, T b) => a.compareTo(b) <= 0 ? a : b;\n  static T max<T extends Comparable>(T a, T b) => a.compareTo(b) >= 0 ? a : b;\n  static double log10(num x) => log(x) / ln10;\n}\n